findings.codeql_raw_query:
/**
 * @name User-controlled expression passed to eval in ImageMath.eval
 * @description Passing a user-controlled expression to eval allows arbitrary code execution (CVE-2023-50447).
 * @kind path-problem
 * @problem.severity error
 * @id py/imagemath-eval-code-injection
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module C implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node n) {
    n.(DataFlow::ParameterNode).getParameter().getName() = "expression"
  }

  predicate isSink(DataFlow::Node n) {
    exists(DataFlow::CallCfgNode c |
      c = API::builtin("eval").getACall() and
      n = c.getArg(0)
    )
  }
}

module F = TaintTracking::Global<C>;

import F::PathGraph

from F::PathNode source, F::PathNode sink
where F::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled expression reaches eval(), allowing arbitrary code execution."
